import React from "react";
import GaugeChart from "react-gauge-chart";

const RiskMeter = ({ score }) => {

  // score should be between 0 - 100
  const riskScore = Math.min(Math.max(score, 0), 100);

  // gauge works between 0 and 1
  const percent = riskScore / 100;

  const getRiskLevel = () => {
    if (riskScore <= 30) return "SAFE";
    if (riskScore <= 60) return "MODERATE";
    return "HIGH RISK";
  };

  const getRiskColor = () => {
    if (riskScore <= 30) return "#16a34a";
    if (riskScore <= 60) return "#facc15";
      return "#dc2626";
  };

  return (
    <div
      style={{
        width: "100%",
        maxWidth: "500px",
        margin: "auto",
        textAlign: "center",
        padding: "20px",
        background: "#ffffff",
        borderRadius: "20px",
        boxShadow: "0 4px 20px rgba(0,0,0,0.1)"
      }}
    >
      <h2 style={{ marginBottom: "10px" }}>
        Food Additive Risk Meter
      </h2>

      <GaugeChart
        id="risk-gauge"
        nrOfLevels={30}
        percent={percent}
        animate={true}
        arcPadding={0.02}
        cornerRadius={5}
        colors={["#22c55e", "#facc15", "#ef4444"]}
        needleColor="#000000"
        needleBaseColor="#000000"
        textColor="#000000"
        animDelay={0}
        style={{ width: "100%" }}
      />

      <div style={{ marginTop: "20px" }}>
        <h1
          style={{
            color: getRiskColor(),
            fontSize: "36px",
            margin: "10px 0"
          }}
        >
          {riskScore}%
           </h1>

        <h2
          style={{
            color: getRiskColor(),
            fontWeight: "bold"
          }}
        >
          {getRiskLevel()}
        </h2>
      </div>
    </div>
  );
};

export default RiskMeter;
